function control(key,descriptor=null){const [k,label,type,extra]=descriptor||fieldMap[key];const required=requiredMeta.has(k);if(type==='checkbox')return '<label class="check"><input type="checkbox" name="'+k+'">'+esc(label)+'</label>';if(type==='repeat')return '<div class="field full" data-repeat="'+k+'"><span>'+esc(label)+'</span><div class="repeatrows"></div><button type="button" class="addRow" data-add-repeat="'+k+'">＋ '+(k==='routeCountries'?'Güzergâh ülkeleri ekle':'Transit gümrükler ekle')+'</button></div>';if(type==='cselect')return '<label class="field"><span>'+esc(label)+(required?' <em>*</em>':'')+'</span><select name="'+k+'">'+countryOptions('')+'</select></label>';return '<label class="field '+(type==='textarea'?'full':'')+'"><span>'+esc(label)+(required?' <em>*</em>':'')+'</span>'+(type==='select'?'<select name="'+k+'">'+extra.map(x=>'<option value="'+esc(x)+'">'+esc(x||'Seçiniz')+'</option>').join('')+'</select>':type==='textarea'?'<textarea name="'+k+'" aria-label="'+esc(label)+'"></textarea>':'<input name="'+k+'" type="'+(type==='date'?'date':'text')+'" '+(type==='number'?'inputmode="decimal"':'')+' '+(type==='country'?'maxlength="2" list="countries"':type==='office'?'list="customs"':'')+' placeholder="'+esc(typeof extra==='string'?extra:'')+'" aria-label="'+esc(label)+'">')+(!descriptor&&hints[k]?'<small>'+esc(hints[k])+'</small>':'')+'</label>'}
