function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function writeDB(next=db){try{localStorage.setItem(DB_KEY,JSON.stringify(next));db=next;$('#saveIndicator').textContent='● Kaydedildi';return true}catch{toast('Kayıt alanı dolu veya kapalı. Yedek indir.');$('#saveIndicator').textContent='Kayıt yapılamadı';return false}}
function nextRef(){const y=new Date().toLocaleDateString('en',{timeZone:'Europe/Istanbul',year:'numeric'});db.pcsSeq=db.pcsSeq||{};let ref;do{db.pcsSeq[y]=(db.pcsSeq[y]||0)+1;ref='PCS'+y+String(db.pcsSeq[y]).padStart(5,'0')}while(db.declarations.some(d=>d.ref===ref));return ref}
