function syncEnsFlags(){const v=[...document.querySelectorAll('[data-repeat="transitOffices"] .repeatitem')].filter(r=>r.querySelector('.ensFlag').checked).map(r=>r.querySelector('input:not(.ensFlag)').value.trim().toUpperCase()).filter(Boolean);form.elements.transitEns.value=v.join('|')}
function syncRoro(){const el=form.elements.roroOperator;if(!el)return;const lab=el.closest('label');lab.hidden=form.elements.transportMode.value!=='Ro-Ro'}
function addRepeat(key,value=''){const row=document.createElement('div');row.className='repeatitem';row.style.cssText='display:flex;gap:8px;margin-bottom:8px';row.innerHTML=(key==='transitOffices'?'<div class="offWrap">':'')+'<input value="'+esc(value)+'" aria-label="'+(key==='routeCountries'?'Güzergâh ülkesi':'Transit gümrük')+'" '+(key==='routeCountries'?'maxlength="2" autocomplete="off" placeholder="Ülke ara: TR, Türkiye…"':'list="customs"')+'>'+(key==='transitOffices'?'</div>':'')+(key==='transitOffices'?'<label class="ensChkL"><input type="checkbox" class="ensFlag"> ENS?</label>':'')+'<button type="button" class="rowDel" aria-label="Satırı kaldır" title="Satırı kaldır">✕</button>';row.querySelector('button').onclick=()=>{row.remove();syncEnsFlags();queueDraft()};if(key==='transitOffices'){const set=(form.elements.transitEns.value||'').split('|').filter(Boolean);row.querySelector('.ensFlag').checked=!!value&&set.includes(String(value).trim().toUpperCase());row.addEventListener('change',e=>{if(e.target.classList.contains('ensFlag')){syncEnsFlags();queueDraft()}});row.querySelector('input:not(.ensFlag)').addEventListener('input',()=>syncEnsFlags())}$('[data-repeat="'+key+'"] .repeatrows').append(row);if(key==='routeCountries')attachCombo(row.querySelector('input'),{minChars:1,emptyText:'Ülke bulunamadı.',search:async(q,limit)=>{await operations.ready;const n=normalizeSearch(q),up=q.trim().toUpperCase();return operations.getCountries().filter(c=>!n||c.code===up||normalizeSearch(c.name).includes(n)||c.code.toLowerCase().startsWith(q.trim().toLowerCase())).sort((a,b)=>{const r=c=>c.code===up?0:normalizeSearch(c.name).startsWith(n)?1:2;return r(a)-r(b)}).slice(0,limit)},item:c=>({title:c.code+' – '+c.name}),onPick:c=>{row.querySelector('input').value=c.code;queueDraft()}})}
function readForm(){const v={};for(const [key,,type]of fields){v[key]=type==='checkbox'?form.elements[key].checked:type==='repeat'?[...document.querySelectorAll('[data-repeat="'+key+'"] input:not(.ensFlag)')].map(x=>x.value.trim().toUpperCase()).filter(Boolean):form.elements[key].value.trim();if(type==='country')v[key]=v[key].toUpperCase()}return normalizeMeta(v)}
const FAC_KEY='t1-facility-codes';const facList=()=>{try{return JSON.parse(localStorage.getItem(FAC_KEY)||'[]')}catch{return[]}};
