function syncFacility(){const el=form.elements.facilityCode;if(!el)return;const lab=el.closest('label');if(!lab.closest('.aeoRow')){const al=form.elements.aeo.closest('label'),row=document.createElement('div');row.className='aeoRow';al.before(row);row.append(al,lab)}if(lab)lab.hidden=!form.elements.aeo.checked;if(form.elements.aeo.checked&&!el.value.trim())el.value=FAC_DEFAULT;let dl=document.getElementById('facilities');if(!dl){dl=document.createElement('datalist');dl.id='facilities';document.body.append(dl);el.setAttribute('list','facilities')}dl.innerHTML=facList().map(c=>'<option value="'+esc(c)+'">').join('')}
function rememberFacility(){const c=(form.elements.facilityCode?.value||'').trim().toUpperCase();if(!c)return;const l=[c,...facList().filter(x=>x!==c)].slice(0,30);try{localStorage.setItem(FAC_KEY,JSON.stringify(l))}catch{}}
function fillForm(values){for(const [key,,type]of fields){if(type==='repeat'){$('[data-repeat="'+key+'"] .repeatrows').innerHTML='';for(const v of values[key]||[])addRepeat(key,v)}else if(type==='checkbox')form.elements[key].checked=!!values[key];else form.elements[key].value=values[key]??''}form.querySelectorAll('.invalid').forEach(e=>e.classList.remove('invalid'));$('#stepError').hidden=true;syncRoro();syncFacility();$('#singleParties').open=!!(values.sender||values.receiver);operations?.reset()}
function queueDraft(){if(!work)return;work.values=readForm();work.status=work.status==='Ön hazırlık'?'Ön hazırlık':'Taslak';renderRail();clearTimeout(draftTimer);draftTimer=setTimeout(flushDraft,250);$('#editorStatus').innerHTML=statusLabel(work.status)}
function flushDraft(){clearTimeout(draftTimer);if(!work)return;work.values=readForm();db.draft={id:work.id,ref:work.ref,values:work.values,records:work.records,step:currentStep,status:work.status,goodDraft:work.goodDraft||null,fin:work.fin};writeDB()}
