function autoHat(d){if(!d.aeo)return;let n=0;for(const g of work.records){if(!g.mrn)continue;const r=hat.createFromGood({mrn:g.mrn,trailer:d.trailer,vehicle:d.vehicle,office:d.departureOffice,declarationRef:d.ref,location:d.facilityCode});if(r&&r.created)n++}if(n)toast(n+' hat bildirimi otomatik hazırlandı (AEO).')}
function saveWork(status=work?.status||'Taslak',message='Taslak kaydedildi.'){if(!work)return false;clearTimeout(draftTimer);work.values=readForm();const existing=db.declarations.find(d=>d.id===work.id),id=work.id||crypto.randomUUID(),now=new Date().toISOString();const declaration={...existing,...work.values,id,ref:existing?.ref||work.ref||nextRef(),status,createdAt:existing?.createdAt||now,updatedAt:now,archived:existing?.archived||false,activity:[...(existing?.activity||[]),{at:now,message}].slice(-60)};const next={...db,declarations:existing?db.declarations.map(d=>d.id===id?declaration:d):[...db.declarations,declaration],draft:null};const previous=localStorage.getItem(goodsKey(id));try{localStorage.setItem(goodsKey(id),JSON.stringify({name:declaration.ref,records:work.records,draft:{},fin:work.fin}));if(!writeDB(next))throw Error('Beyanname kaydedilemedi');work.id=id;work.ref=declaration.ref;work.status=status;location.hash='edit/'+id;$('#editorTitle').textContent=work.ref;$('#editorStatus').innerHTML=statusLabel(status);renderRail();try{autoHat(declaration)}catch{}return true}catch{try{if(previous===null)localStorage.removeItem(goodsKey(id));else localStorage.setItem(goodsKey(id),previous)}catch{}toast('Taslak kaydedilemedi. Yedek indirerek mevcut çalışmayı koru.');return false}}
form.addEventListener('input',queueDraft);form.addEventListener('change',queueDraft);form.onsubmit=e=>e.preventDefault();$('#metadataFields').onclick=e=>{const b=e.target.closest('[data-add-repeat]');if(b){addRepeat(b.dataset.addRepeat);queueDraft()}};
const VIEWS={list:['navList','Beyannameler'],editor:['navNew','T1 yazımı'],connection:['navConnection','Gönderim bağlantısı'],references:['navReferences','GTİP kataloğu'],accounting:['navAccounting','Muhasebe'],ens:['navEns','ENS beyannameleri'],companies:['navCompanies','Firmalar'],vehicles:['navVehicles','Araçlar'],hat:['navHat','Hat bildirimleri'],finance:['navFinance','Fiyat ayarları']};
function showView(name){for(const id of Object.keys(VIEWS))$('#'+id+'View').hidden=id!==name;document.querySelectorAll('.nav').forEach(b=>b.classList.remove('active'));$('#'+VIEWS[name][0]).classList.add('active');$('#breadcrumb').innerHTML='Çalışma alanı <i>/</i> '+VIEWS[name][1];window.scrollTo({top:0,behavior:'smooth'})}
function startEditor(id=null,step=0,resume=true){clearTimeout(draftTimer);let d=id?db.declarations.find(x=>x.id===id):null;if(id&&!d){showList();return}const draft=resume&&db.draft&&db.draft.id===id?db.draft:null;work={id,ref:d?.ref||draft?.ref||'',status:draft?.status||d?.status||'Taslak',values:normalizeMeta({...defaults,...(d||{}),...(draft?.values||{})}),records:(draft?.records||readGoods(id).records).map(normalizeGood),goodDraft:draft?.goodDraft||null,fin:Fin.normalizeFin(draft?.fin??(id?readGoods(id).fin:null))};if(!id&&!draft)work.records=[];fillForm(work.values);currentStep=draft?Math.min(6,Number(draft.step)||0):step;$('#editorTitle').textContent=work.ref||'Yeni T1 Beyannamesi';$('#editorSubtitle').textContent=work.ref?'Bilgilerini güncelle ve kontrol adımlarını tamamla.':'Gümrükten son kontrole, adım adım yazım.';$('#editorStatus').innerHTML=statusLabel(work.status);showView('editor');setStep(currentStep);if(work.goodDraft){setStep(3);openGood(work.goodDraft.editId||null)}location.hash=id?'edit/'+id:'new'}
function newEditor(){if(work)flushDraft();if(db.draft)confirmAction('Yeni T1 aç','Yarım kalan çalışmanın yerine yeni bir yazım açılacak. Kaydedilmiş beyannamelerin korunur. Mevcut çalışmayı sürdürmek için listede “Yazıma devam et” seçebilirsin.',()=>{db.draft=null;writeDB();startEditor(null,0,false)});else startEditor(null,0,false)}
function stepComplete(i){if(!work)return false;const v=work.values,issues=allProblems(v,work.records);if(i===6)return work.status==='Kontrol edildi'&&!issues.length;const filled=i===0?!!v.departureOffice&&!!v.arrivalOffice:i===1?!!v.carrier&&(!!v.vehicle||!!v.trailer):i===2?!!v.transportMode:i===3?work.records.length>0:i===5?!!(work.fin&&work.fin.lines.length):!!v.principal&&!!v.guaranteeType;return filled&&!issues.some(x=>x.step===i)}
function setStep(index){currentStep=Math.max(0,Math.min(6,index));$('#stepper').innerHTML=steps.map((s,i)=>'<button type="button" data-step="'+i+'" class="'+(i===currentStep?'current':stepComplete(i)?'complete':'')+'" '+(i===currentStep?'aria-current="step"':'')+'><b>'+(stepComplete(i)?'✓':i+1)+'</b>'+s.name+'</button>').join('');const s=steps[currentStep];$('#stepEyebrow').textContent='ADIM '+String(currentStep+1).padStart(2,'0');$('#stepTitle').textContent=s.title;$('#stepDescription').textContent=s.description;$('#stepNumber').textContent=(currentStep+1)+' / 7';document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=Number(p.dataset.panel)!==currentStep);$('#goodsStep').hidden=currentStep!==3;$('#reviewStep').hidden=currentStep!==6;$('#financeStep').hidden=currentStep!==5;$('#previousStep').disabled=currentStep===0;$('#nextStep').hidden=currentStep===6;$('#markReviewed').hidden=currentStep!==6;$('#stepFooter').textContent='Eksik bilgilerle taslak kaydedebilirsin.';$('#stepError').hidden=true;$('#railTipTitle').textContent=s.tipTitle;$('#railTip').textContent=s.tip;renderRail();if(currentStep===3)renderGoods();if(currentStep===4)refreshGuarantee();if(currentStep===5)renderFinance();if(currentStep===6)renderReview();flushDraft()}
$('#stepper').onclick=e=>{const b=e.target.closest('[data-step]');if(b){flushDraft();setStep(Number(b.dataset.step))}};$('#previousStep').onclick=()=>{flushDraft();setStep(currentStep-1)};
$('#nextStep').onclick=()=>{work.values=readForm();const issues=allProblems(work.values,work.records).filter(x=>x.step===currentStep);if(issues.length){showStepErrors(issues);return}if(saveWork(work.status,'Taslak bilgileri kaydedildi.')){setStep(currentStep+1);flushDraft();window.scrollTo({top:100,behavior:'smooth'})}};
function showStepErrors(issues){$('#stepError').hidden=false;$('#stepError').innerHTML=issues.map(x=>esc(x.message)).join('<br>');for(const issue of issues){const e=form.elements[issue.key];if(e){e.classList.add('invalid');e.closest('details')?.setAttribute('open','')}}$('#stepError').scrollIntoView({behavior:'smooth',block:'center'})}
