$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=await parseFile(f);if(v.format==='t1-ncts'&&Array.isArray(v.db?.declarations)){let added=0;for(const value of v.db.declarations){if(!value?.id||!Array.isArray(v.goods?.[value.id]?.records))continue;if(db.declarations.some(d=>d.id===value.id||d.sourceBackupId===value.id))continue;const id=crypto.randomUUID(),now=new Date().toISOString();let ref=text(value.ref)||nextRef();if(db.declarations.some(d=>d.ref===ref))ref=nextRef();const d={...normalizeMeta(value),id,ref,sourceBackupId:value.id,status:'Ön hazırlık',archived:!!value.archived,createdAt:Number.isFinite(Date.parse(value.createdAt))?value.createdAt:now,updatedAt:now,activity:[{at:now,message:'Yedekten içe aktarıldı; yeniden kontrol bekliyor.'}]};localStorage.setItem(goodsKey(id),JSON.stringify({name:ref,records:v.goods[value.id].records.map(normalizeGood).map(g=>({...g,id:crypto.randomUUID(),reviewed:false})),fin:v.goods[value.id].fin||null}));db.declarations.push(d);added++}if(Array.isArray(v.companies))await references.importRecords(v.companies);if(v.plateCountries)await operations.restorePlateCountries(v.plateCountries);if(v.accounting)accounting.importData(v.accounting);if(v.ens)ens.importData(v.ens);if(Array.isArray(v.plates))await plates.importData(v.plates);if(Array.isArray(v.hat))hat.importData(v.hat);if(v.finance){const inc=Fin.normalize(v.finance),cur=getFinance();for(const it of inc.items)if(!cur.items.some(x=>x.id===it.id))cur.items.push(it);for(const r of inc.rules)if(!cur.rules.some(x=>x.id===r.id))cur.rules.push(r);for(const [k,val] of Object.entries(inc.rates))if(!cur.rates[k])cur.rates[k]=val;saveFinance(cur)}db.counter=Math.max(db.counter,Number(v.db.counter)||0);if(v.db.draft&&!db.draft){const draft=v.db.draft;db.draft={id:null,ref:'',values:normalizeMeta(draft.values),records:Array.isArray(draft.records)?draft.records.map(normalizeGood).map(g=>({...g,reviewed:false})):[],step:Math.max(0,Math.min(5,Number(draft.step)||0)),status:'Ön hazırlık',goodDraft:draft.goodDraft?{editId:draft.goodDraft.editId||null,values:{...normalizeGood(draft.goodDraft.values),reviewed:false}}:null}}writeDB();renderList();toast(added+' beyanname içe alındı.')}else if(v.format==='t1-preparation'&&Array.isArray(v.goods)){const id=importRecords(v.goods,v.declaration?.customer||f.name),d=db.declarations.find(x=>x.id===id);Object.assign(d,normalizeMeta(v.declaration));writeDB();startEditor(id,5,false)}else if(Array.isArray(v.records)){startEditor(importRecords(v.records,v.name||f.name),5,false)}else throw Error('T1 yedek veya PCS Excel dosyası seç.')}catch(err){toast('İçe alınamadı: '+err.message)}finally{e.target.value=''}};
$('#previewPrint').onclick=()=>{work.values=readForm();const d=work.values;$('#printArea').innerHTML='<h1>'+esc(work.ref||'Taslak')+' · T1 hazırlık formu</h1><div class="printgrid">'+groups.map(([title,fs])=>'<section><h2>'+title+'</h2>'+fs.map(([key,label,type])=>'<p><b>'+esc(label)+':</b> '+esc(type==='checkbox'?(d[key]?'Evet':'Hayır'):Array.isArray(d[key])?d[key].join(' → '):d[key]||'—')+'</p>').join('')+'</section>').join('')+'</div><h2>Eşya bilgileri</h2><table><tr><th>MRN / GTİP</th><th>Tanım / Firmalar</th><th>Brüt / Net / Kap</th><th>Fatura</th></tr>'+work.records.map(g=>'<tr><td>'+esc(g.mrn)+'<br>'+esc(g.gtip)+'</td><td>'+esc(g.description)+'<br>'+esc(g.sender)+' → '+esc(g.receiver)+'</td><td>'+esc(g.gross)+' / '+esc(g.net)+' / '+esc(g.packages)+'</td><td>'+esc(g.invoice)+'<br>'+esc(g.invoiceDate)+'<br>'+esc(g.amount)+' '+esc(g.currency)+'</td></tr>').join('')+'</table><p>Hazırlık formudur. Resmî tescil veya transit refakat belgesi değildir.</p>';window.print()};
