{const host=$('[data-repeat="routeCountries"]');if(host){const bar=document.createElement('div');bar.className='routePreset';bar.innerHTML='<label>Rota seçiniz <select aria-label="Hazır rota"><option value="">Rota seçiniz…</option>'+ROUTES.map((r,i)=>'<option value="'+i+'">'+esc(r[0])+'</option>').join('')+'</select></label>';host.closest('.steppanel').prepend(bar);host.closest('.steppanel').classList.add('routePanel');bar.querySelector('select').onchange=async e=>{const r=ROUTES[e.target.value];if(!r)return;await operations.ready;if(r[1])operations.setBorder(r[1]);host.querySelector('.repeatrows').innerHTML='';form.elements.transitEns.value='';for(const c of r[2])addRepeat('routeCountries',c);const tr=host.closest('form').querySelector('[data-repeat="transitOffices"] .repeatrows');tr.innerHTML='';for(const c of r[3])addRepeat('transitOffices',operations.officeLabel(c));queueDraft();e.target.value='';toast('Rota dolduruldu: '+r[2].join(' → ')+(r[1]?' · sınır gümrüğü '+r[1]:'')+(r[3].length?' · '+r[3].length+' transit gümrük':''))}}}
