const financePanel=mountFinancePanel($('#financeStep'),{getState:()=>({fin:work.fin,kind:'t1',customerDefault:work.values.customer||'',permitted:!!work.values.aeo,goods:work.records}),setCustomer:name=>{form.elements.customer.value=name;queueDraft()},getLinked:()=>work&&work.ref?ens.list().filter(r=>!r.archived&&r.ncts===work.ref).map(r=>({id:r.id,ref:r.ref,lines:(r.fin&&r.fin.lines)||[]})):[],commit:fin=>{work.fin=fin;queueDraft()},getCompanies:()=>references.getCompanies(),toast,confirmAction,onGuarantee:g=>applyGuarantee(g)});
renderFinance=()=>{if(work){work.values=readForm();financePanel.render()}};
const applyCustomerProfile=()=>{if(!work)return;const name=form.elements.customer.value.trim(),pr=name?Fin.firmProfile(getFinance(),name):null;if(pr&&form.elements.aeo.checked!==pr.permitted){form.elements.aeo.checked=pr.permitted;syncFacility();queueDraft();toast(pr.permitted?'Bu müşteri izinli gönderici (AEO) olarak işaretlendi.':'Bu müşteri için izinli gönderici işareti kaldırıldı.')}};
form.elements.customer.addEventListener('change',applyCustomerProfile);form.elements.customer.addEventListener('blur',applyCustomerProfile);
