function route(){const h=location.hash.slice(1);if(h==='new')startEditor(null,0,true);else if(h.startsWith('edit/'))startEditor(h.slice(5),0,true);else if(h.startsWith('declaration/'))startEditor(h.slice(12),6,true);else if(h==='connection')showConnection();else if(h==='references')showReferences();else if(h==='companies'||h==='vehicles')showList2(h);else if(h==='hat')showHat();else if(h==='finance')showFinance();else if(h==='accounting')showAccounting();else if(h==='ens')showEns(null);else if(h.startsWith('ens/'))showEns(h.slice(4));else showList()}
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h==='list'&&!$('#listView').hidden||h==='connection'&&!$('#connectionView').hidden||h==='references'&&!$('#referencesView').hidden||h==='finance'&&!$('#financeView').hidden||(h==='companies'||h==='vehicles')&&!$('#'+h+'View').hidden||h==='new'&&!$('#editorView').hidden&&!work?.id||h==='edit/'+work?.id&&!$('#editorView').hidden)return;route()});window.addEventListener('beforeunload',()=>{if(work)flushDraft()});route();

const enrichGoods=()=>work.records.map(g=>{const c=references.listCompanies(),o={...g};for(const side of ['sender','receiver']){const f=g[side]?exactCompany(c,g[side]):null;if(!f)continue;if(!o[side+'Address'])o[side+'Address']=f.address||'';if(!o[side+'City'])o[side+'City']=f.city||'';if(!o[side+'Postal'])o[side+'Postal']=f.postal||'';if(!o[side+'Country'])o[side+'Country']=f.country||'';if(!o[side+'Eori'])o[side+'Eori']=f.eori||''}if(!o.receiverCountry)o.receiverCountry=work.values.destinationCountry||'';return o});
$('#printT1').onclick=()=>{work.values=readForm();printHtml((work.ref||'T1')+' T1 Taslak',t1Draft(work.values,enrichGoods(),work.ref))};$('#printCmr').onclick=()=>{work.values=readForm();const goods=enrichGoods(),groups=cmrGroups(goods,work.values);if(groups.length<=1){printHtml((work.ref||'T1')+' CMR',cmr(work.values,goods,work.ref));return}
 let dlg=document.getElementById('cmrDialog');if(!dlg){dlg=document.createElement('dialog');dlg.id='cmrDialog';document.body.append(dlg)}
 dlg.innerHTML='<h2>Toplu CMR</h2><p>Bu T1\'de '+groups.length+' farklı gönderici / alıcı çifti var. Her çift için ayrı CMR hazırlanır (her biri kendi sayfasında).</p><div class="cmrPick">'+groups.map((gr,i)=>'<label><input type="checkbox" data-i="'+i+'" checked><span><b>'+esc(gr.sender||'Gönderici yok')+'</b> → '+esc(gr.receiver||'Alıcı yok')+'<small>'+gr.goods.length+' eşya · '+gr.goods.map(g=>g.mrn).filter(Boolean).slice(0,3).join(', ')+'</small></span><button type="button" class="quiet" data-one="'+i+'">Yalnız bunu yazdır</button></label>').join('')+'</div><div class="dialogactions"><button type="button" data-close>Kapat</button><button type="button" class="primary" data-all>Seçilenleri yazdır</button></div>';
 dlg.onclick=e=>{if(e.target.closest('[data-close]')){dlg.close();return}const one=e.target.closest('[data-one]');if(one){e.preventDefault();printHtml((work.ref||'T1')+' CMR',cmr(work.values,groups[Number(one.dataset.one)].goods,work.ref));return}if(e.target.closest('[data-all]')){const sel=[...dlg.querySelectorAll('input[data-i]:checked')].map(x=>groups[Number(x.dataset.i)]);if(!sel.length){toast('En az bir CMR seç.');return}dlg.close();printHtml((work.ref||'T1')+' CMR',cmrAll(work.values,sel,work.ref))}};dlg.showModal()};

